-- MY GYM London - 85 more exercises for the library (shoulders, triceps, biceps, chest, back, legs, abs, lower back)
-- Paste into Supabase Dashboard -> SQL Editor -> Run (safe to re-run: skips any name already in the library, any capitals)
-- Triceps and biceps are both in the "Arms" group; abs are "Core"; lower back is its own group "Lower back".
with new_rows(name, muscle_group, equipment, how_to, sort) as (values
-- Shoulders (10)
('Barbell push press','Shoulders','Barbell','Bar at the collarbones, dip the knees slightly, drive up with the legs and press the bar overhead.',179),
('Landmine press','Shoulders','Landmine','Hold the end of the bar at the shoulder, press up and forward until the arm is straight, lower slowly.',180),
('Single-arm dumbbell press','Shoulders','Dumbbell','Dumbbell at the shoulder, brace the core, press straight overhead without leaning, lower under control.',181),
('Bent-over lateral raise','Shoulders','Dumbbell','Hinge forward with a flat back, raise the dumbbells out to the sides to shoulder height, lower slowly.',182),
('Cable front raise','Shoulders','Cable','Low pulley between the feet, raise the handle straight in front to shoulder height, lower slowly.',183),
('Cable upright row','Shoulders','Cable','Low pulley with a bar or rope, pull up towards the chest with the elbows leading, lower slowly.',184),
('Plate front raise','Shoulders','Plate','Hold a plate at the sides of the rim, raise it in front to eye level with straight arms, lower slowly.',185),
('Barbell shrug','Shoulders','Barbell','Hold the bar at the thighs, lift the shoulders straight up towards the ears, pause, lower slowly.',186),
('Pike push-up','Shoulders','Bodyweight','Hips high in an upside-down V, bend the elbows to lower the head towards the floor, press back up.',187),
('Scaption raise','Shoulders','Dumbbell','Raise the dumbbells in a Y shape, 30 degrees in front of the body, thumbs up, to shoulder height.',188),
