('Nordic hamstring curl','Legs','Bodyweight','Kneel with the feet anchored, lower the body forward as slowly as you can, push back up with the hands.',237),
('Dumbbell split squat','Legs','Dumbbell','Staggered stance, lower the back knee towards the floor, push through the front heel to stand.',238),
-- Abs (15) -> Core
('Hanging windshield wiper','Core','Pull-up bar','Hang with legs raised, rotate them side to side under control without swinging.',239),
('Toes-to-bar','Core','Pull-up bar','Hang from the bar and lift the toes up to touch it, lower slowly without swinging.',240),
('Hollow body hold','Core','Bodyweight','Lie on your back, lower back pressed down, lift shoulders and legs and hold.',241),
('Reverse crunch','Core','Bodyweight','Lie on your back, knees bent, curl the hips off the floor bringing the knees towards the chest.',242),
('Decline sit-up','Core','Bodyweight','Feet secured on a decline bench, curl up to sitting and lower slowly.',243),
('Dragon flag','Core','Bodyweight','Shoulders on a bench, body straight, lower the legs and hips as one piece and raise them back up.',244),
('L-sit hold','Core','Bodyweight','Support yourself on straight arms with the legs straight out in front, and hold.',245),
('Weighted sit-up','Core','Dumbbell','Hold a dumbbell at the chest, curl up to sitting and lower slowly.',246),
('Cable side crunch','Core','Cable','Stand side-on to a high pulley, bend sideways at the waist against the cable, return slowly.',247),
('Plank to push-up','Core','Bodyweight','From forearm plank, press up onto the hands one arm at a time, then lower back down.',248),
('Plank hip dips','Core','Bodyweight','In a forearm plank, rotate and dip the hips gently to one side, then the other.',249),
('Heel taps','Core','Bodyweight','Lie on your back with knees bent, reach one hand then the other to the heel by crunching sideways.',250),
('Suitcase carry','Core','Dumbbell','Hold one heavy dumbbell at your side, walk tall without leaning, then swap hands.',251),
('Kettlebell windmill','Core','Kettlebell','Kettlebell overhead, hinge to the side with the free hand sliding down the leg, then stand up.',252),
('Hanging oblique knee raise','Core','Pull-up bar','Hang from the bar and lift both knees up towards one side of the body, alternating sides.',253),
-- Lower back (10)
('Weighted back extension','Lower back','Dumbbell','On a back extension bench, hold a dumbbell at the chest, lower and lift the torso with a flat back.',254),
('Seated good morning','Lower back','Barbell','Seated with the bar on the upper back, hinge forward with a flat back and sit tall again.',255),
('Alternating superman','Lower back','Bodyweight','Lie face down, lift opposite arm and leg together, lower, then switch sides.',256),
('Prone cobra','Lower back','Bodyweight','Lie face down, lift the chest and arms off the floor, squeeze the back and hold.',257),
('Reverse plank','Lower back','Bodyweight','Sit with legs straight, hands behind, lift the hips until the body is straight and hold.',258),
('Kettlebell good morning','Lower back','Kettlebell','Hold a kettlebell at the chest, push the hips back with a flat back, then stand tall.',259),
('Single-leg good morning','Lower back','Bodyweight','Hinge forward on one leg with the other leg lifting behind, flat back, then stand tall.',260),
('Smith good morning','Lower back','Smith bar','Smith bar on the upper back, soft knees, hinge at the hips with a flat back and stand.',261),
('Dumbbell good morning','Lower back','Dumbbell','Dumbbell held at the chest, hinge at the hips with a flat back until the hamstrings stretch, stand.',262),
('Bodyweight good morning','Lower back','Bodyweight','Hands behind the head, hinge at the hips with a flat back, then drive the hips forward to stand.',263)
)
insert into public.exercises (name, muscle_group, equipment, how_to, sort)
select n.name, n.muscle_group, n.equipment, n.how_to, n.sort
from new_rows n
where not exists (select 1 from public.exercises e where lower(e.name) = lower(n.name));
